(3243490, 454097, 70692, '<td valign="top">Best car in the world.  Gorgeous.</td>', 'Best car in the world.  Gorgeous.', '2007-01-17 00:12:24.000000', NULL, 1),
(3243495, 453933, 51638, '<td valign="top">This is a GREAT shot, but it appears to me to be more a shallow DOF shot, rather than the background having been blurred due to motion panning.</td>', 'This is a GREAT shot, but it appears to me to be more a shallow DOF shot, rather than the background having been blurred due to motion panning.', '2007-01-17 00:13:41.000000', NULL, 1),
(3243505, 454254, 51638, '<td valign="top">Really gives a sense of motion (in fact it''s making my eyes go funny looking at it!). Well done.</td>', 'Really gives a sense of motion (in fact it''s making my eyes go funny looking at it!). Well done.', '2007-01-17 00:14:37.000000', NULL, 1),
(3243511, 452506, 51638, '<td valign="top">Sorry, but this appears to me to be of a motion blur shot than motion panning.</td>', 'Sorry, but this appears to me to be of a motion blur shot than motion panning.', '2007-01-17 00:15:37.000000', NULL, 1),
(3243516, 454141, 16241, '<td valign="top">great shot</td>', 'great shot', '2007-01-17 00:16:07.000000', NULL, 1),
(3243519, 454318, 51638, '<td valign="top">Technically very well done.</td>', 'Technically very well done.', '2007-01-17 00:16:32.000000', NULL, 1),
(3243524, 454204, 51638, '<td valign="top">You haven''t really used the MP technique to bring your subject out of the background enough IMO.</td>', 'You haven''t really used the MP technique to bring your subject out of the background enough IMO.', '2007-01-17 00:17:27.000000', NULL, 1),
(3243533, 452770, 51638, '<td valign="top">Yup, this works. And I like that you got the passenger looking at the camera. Well done.</td>', 'Yup, this works. And I like that you got the passenger looking at the camera. Well done.', '2007-01-17 00:18:47.000000', NULL, 1),
(3243544, 454097, 66192, '<td valign="top">Blacks look a bit noisey, nice shot though</td>', 'Blacks look a bit noisey, nice shot though', '2007-01-17 00:19:34.000000', NULL, 1),
(3243547, 453929, 51638, '<td valign="top">More motion blur than motion panning it seems to me.</td>', 'More motion blur than motion panning it seems to me.', '2007-01-17 00:19:56.000000', NULL, 1),
(3243558, 454150, 16241, '<td valign="top">great shot, i love it.</td>', 'great shot, i love it.', '2007-01-17 00:21:17.000000', NULL, 1),
(3243564, 453620, 51638, '<td valign="top">I''d say your shutter speed was a little too fast to have adequately blurred the background for this to be really effective.</td>', 'I''d say your shutter speed was a little too fast to have adequately blurred the background for this to be really effective.', '2007-01-17 00:21:46.000000', NULL, 1),
(3243574, 453816, 15711, '<td valign="top">Gorgeous, gorgeous.  One of the best I''ve seen so far.  NOt a fan of the gold of the frame, but the rest is smack on.</td>', 'Gorgeous, gorgeous.  One of the best I''ve seen so far.  NOt a fan of the gold of the frame, but the rest is smack on.', '2007-01-17 00:23:02.000000', NULL, 1),
(3243585, 453489, 15711, '<td valign="top">I''d love to see either where he''s going or where he''s been. It seems a tad "tight" to me as it is. Great colors and it certain has the subject focused with the rest of the world whizzing by.</td>', 'I''d love to see either where he''s going or where he''s been. It seems a tad "tight" to me as it is. Great colors and it certain has the subject focused with the rest of the world whizzing by.', '2007-01-17 00:23:50.000000', NULL, 1),
(3243588, 454211, 19982, '<td valign="top">There''s just not a lot of background blur on this image.  To make a truly succesful "motion panning shot", you need to run the shutter at a much slower speed than you would normally use and then, as accurately as possible, follow your subject with the camera (that much you appear to have done well, you just needed a slower shutter speed to blur the background).</td>', 'There''s just not a lot of background blur on this image.  To make a truly succesful "motion panning shot", you need to run the shutter at a much slower speed than you would normally use and then, as accurately as possible, follow your subject with the camera (that much you appear to have done well, you just needed a slower shutter speed to blur the background).', '2007-01-17 00:24:00.000000', NULL, 1),
(3243595, 452952, 51638, '<td valign="top">I can''t pick out the object you panned. Seems to be more of a motion blur shot than MP.</td>', 'I can''t pick out the object you panned. Seems to be more of a motion blur shot than MP.', '2007-01-17 00:24:26.000000', NULL, 1),
(3243602, 454141, 15711, '<td valign="top">I love this!!</td>', 'I love this!!', '2007-01-17 00:25:04.000000', NULL, 1),
