(3246636, 451225, 5112, '<td valign="top">Wait till she is a teenager :)  I''m not sure if there is any panning in this image.  I think that the subject (the beautiful little feet walking on your face) would probably be better suited for a different approach, one were things were sharper and more contrasty and clearer.</td>', 'Wait till she is a teenager :)  I''m not sure if there is any panning in this image.  I think that the subject (the beautiful little feet walking on your face) would probably be better suited for a different approach, one were things were sharper and more contrasty and clearer.', '2007-01-17 12:35:24.000000', NULL, 1),
(3246639, 451225, 69604, '<td valign="top">dont really see the motion? but its a fun picture</td>', 'dont really see the motion? but its a fun picture', '2007-01-17 12:35:51.000000', NULL, 1),
(3246646, 454109, 5112, '<td valign="top">If this is done with real panning, then congratulations, the bullet is perfectly clear against a background that implies motion.</td>', 'If this is done with real panning, then congratulations, the bullet is perfectly clear against a background that implies motion.', '2007-01-17 12:36:20.000000', NULL, 1),
(3246655, 453818, 31443, '<td valign="top">Just love seeing these strong animals run, they are so amazing. Nice capture with the rider, she is holding a flag in her hand I hope..</td>', 'Just love seeing these strong animals run, they are so amazing. Nice capture with the rider, she is holding a flag in her hand I hope..', '2007-01-17 12:37:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3246659, 454036, 66353, '<td valign="top">Beautiful - I really like the effect you''ve created here. And the colours are great...</td>', 'Beautiful - I really like the effect you''ve created here. And the colours are great...', '2007-01-17 12:37:37.000000', NULL, 1),
(3246663, 453933, 5792, '<td valign="top">Incredibly nice stop action image. Colors, lighting and exposure are right on. (Of course that could be accomplished with RAW image processing from the original. lol!) Nice sharpness and excellent perspective on the hawk.<br/> <br/>The image looks to be soft focused rather than motion panned. It does not show much background motion. That is probably because you took it at a fast shutter speed even though you obviously were panning the bird. Some voters will probably fault this fine image for that in this particular challenge.</td>', 'Incredibly nice stop action image. Colors, lighting and exposure are right on. (Of course that could be accomplished with RAW image processing from the original. lol!) Nice sharpness and excellent perspective on the hawk. The image looks to be soft focused rather than motion panned. It does not show much background motion. That is probably because you took it at a fast shutter speed even though you obviously were panning the bird. Some voters will probably fault this fine image for that in this particular challenge.', '2007-01-17 12:39:17.000000', NULL, 1),
(3246670, 454036, 5112, '<td valign="top">This is absolutely lovely!  ~10  The gulls look like they have veils.  It almost looks like a multiple-exposure.</td>', 'This is absolutely lovely!  ~10  The gulls look like they have veils.  It almost looks like a multiple-exposure.', '2007-01-17 12:40:33.000000', NULL, 1),
(3246672, 453539, 69604, '<td valign="top">dont really like the red/orange glare</td>', 'dont really like the red/orange glare', '2007-01-17 12:40:48.000000', NULL, 1),
(3246674, 454079, 5112, '<td valign="top">I like this one.  The look of determination on her face, the blur of the hands, the flying hair, very good.  ~8</td>', 'I like this one.  The look of determination on her face, the blur of the hands, the flying hair, very good.  ~8', '2007-01-17 12:41:22.000000', NULL, 1),
(3246675, 453816, 31443, '<td valign="top">Beautiful image, the background is really special for the color of bird</td>', 'Beautiful image, the background is really special for the color of bird', '2007-01-17 12:41:22.000000', NULL, 1),
(3246679, 454109, 69604, '<td valign="top">how did you catch that shot? its cool if it real. 9</td>', 'how did you catch that shot? its cool if it real. 9', '2007-01-17 12:42:04.000000', NULL, 1),
(3246699, 453742, 24389, '<td valign="top">i think this is the best shot i''ve seen so far</td>', 'i think this is the best shot i''ve seen so far', '2007-01-17 12:46:17.000000', NULL, 1),
(3246706, 453560, 5792, '<td valign="top">Like the perspective of this image. Decent clarity on your main subjects. Lighting, color and action are well captured.<br/> <br/>This image has the appearance that it was taking from the moving platform and not from panning per se and perhaps some voters will think it is not ''true'' motion panning.</td>', 'Like the perspective of this image. Decent clarity on your main subjects. Lighting, color and action are well captured. This image has the appearance that it was taking from the moving platform and not from panning per se and perhaps some voters will think it is not ''true'' motion panning.', '2007-01-17 12:47:07.000000', NULL, 1),
(3246713, 453977, 70661, '<td valign="top">I love how you caught this shot but I can''t really see the action (motion) in the background.</td>', 'I love how you caught this shot but I can''t really see the action (motion) in the background.', '2007-01-17 12:48:45.000000', NULL, 1),
(3246759, 454345, 5112, '<td valign="top">Wow, looks like one of those commercials for cameras.  ~10</td>', 'Wow, looks like one of those commercials for cameras.  ~10', '2007-01-17 12:56:24.000000', NULL, 1),
(3246773, 454219, 5112, '<td valign="top">I like this image quite a bit, but it isn''t panning.  There is no subject being panned against a  background, here the subject is moving with everything else.  Panning would be more like if you were to point the camera out the side window of your car, and you''d get a vehicle driving along at the same speed as yours, then you might get panning (sort of, actually it''s not real panning).  Real panning would be you standing by the side of the road and following a car driving by with the camera, moving the camera at the same speed (relative) as the car while holding down the shutter.</td>', 'I like this image quite a bit, but it isn''t panning.  There is no subject being panned against a  background, here the subject is moving with everything else.  Panning would be more like if you were to point the camera out the side window of your car, and you''d get a vehicle driving along at the same speed as yours, then you might get panning (sort of, actually it''s not real panning).  Real panning would be you standing by the side of the road and following a car driving by with the camera, moving the camera at the same speed (relative) as the car while holding down the shutter.', '2007-01-17 12:58:29.000000', NULL, 1),
(3246777, 453191, 35357, '<td valign="top">Silly photgrapher! :-)</td>', 'Silly photgrapher! :-)', '2007-01-17 12:59:40.000000', NULL, 1),
(3246789, 453930, 5792, '<td valign="top">The primary purpose in motion panning is to capture a clear image of a moving subject that is possible only by smoothly twisting as you follow the main subject and take the picture. You will usually use a longer exposure time to show the subject''s movement against the background. That produces a very smooth motion blur in the background.<br/> <br/>In this image it is clear there is jerky motion and because of that the bus is not clear. You will see many good examples of fine motion panning on many of the images in this challenge.</td>', 'The primary purpose in motion panning is to capture a clear image of a moving subject that is possible only by smoothly twisting as you follow the main subject and take the picture. You will usually use a longer exposure time to show the subject''s movement against the background. That produces a very smooth motion blur in the background. In this image it is clear there is jerky motion and because of that the bus is not clear. You will see many good examples of fine motion panning on many of the images in this challenge.', '2007-01-17 13:01:27.000000', NULL, 1),
(3246790, 454255, 5792, '<td valign="top">Nice capture of the puck on the stick!</td>', 'Nice capture of the puck on the stick!', '2007-01-17 13:01:59.000000', NULL, 1),
