(3247791, 453933, 70298, '<td valign="top">centered well and great action shot! Gr8. 8</td>', 'centered well and great action shot! Gr8. 8', '2007-01-17 16:03:40.000000', NULL, 1),
(3247794, 454088, 46031, '<td valign="top">With a moving object it''s usually better to leave some room for the object to "move into". I like the shadow behind the bike, though, so I wouldn''t have cropped there, either.</td>', 'With a moving object it''s usually better to leave some room for the object to "move into". I like the shadow behind the bike, though, so I wouldn''t have cropped there, either.', '2007-01-17 16:04:08.000000', NULL, 1),
(3247797, 453532, 70298, '<td valign="top">Gr8 photo! like the colours and fits the criteria well.</td>', 'Gr8 photo! like the colours and fits the criteria well.', '2007-01-17 16:04:35.000000', NULL, 1),
(3247798, 454158, 57229, '<td valign="top">Blimey. Couldn''t sort of bottle that energy and... never mind. 6</td>', 'Blimey. Couldn''t sort of bottle that energy and... never mind. 6', '2007-01-17 16:04:49.000000', NULL, 1),
(3247801, 453439, 46031, '<td valign="top">I like the colors and the gradient from dark in the background to almost blown in the foreground. However, you can''t motion PAN if the object is moving toward you. This results in the dog being blurred - only the head is kind of sharp. I like the picture, it has a nice kind of impressionist feel to it, I just don''t think it fits this challenge all that well...</td>', 'I like the colors and the gradient from dark in the background to almost blown in the foreground. However, you can''t motion PAN if the object is moving toward you. This results in the dog being blurred - only the head is kind of sharp. I like the picture, it has a nice kind of impressionist feel to it, I just don''t think it fits this challenge all that well...', '2007-01-17 16:05:47.000000', NULL, 1),
(3247803, 453577, 57229, '<td valign="top">wrong thing(s) blurred 3</td>', 'wrong thing(s) blurred 3', '2007-01-17 16:05:51.000000', NULL, 1),
