(3247817, 453933, 59031, '<td valign="top">Great photo, good DOF, but the background doesn''t have that motion blur that i think it really needed for this particular challenge.</td>', 'Great photo, good DOF, but the background doesn''t have that motion blur that i think it really needed for this particular challenge.', '2007-01-17 16:08:42.000000', NULL, 1),
