(3258204, 450965, 54540, '<td valign="top">This is a FANTASTIC shot!  I''m not sure how the voters will react regarding whether or not this is classic "Motion Panning", but a fantastic shot here.  Well done!  (I''m presuming this camera is mounted to the vehicle.)</td>', 'This is a FANTASTIC shot!  I''m not sure how the voters will react regarding whether or not this is classic "Motion Panning", but a fantastic shot here.  Well done!  (I''m presuming this camera is mounted to the vehicle.)', '2007-01-19 23:30:29.000000', NULL, 1),
(3258207, 454036, 23394, '<td valign="top">an absolute masterpiece, probably wasted on this audience.</td>', 'an absolute masterpiece, probably wasted on this audience.', '2007-01-19 23:31:47.000000', NULL, 1),
(3258209, 454097, 23394, '<td valign="top">nice, but boring.  also a bit pixelated.  maybe if you had punched up the saturization some, it might be more eye-gripping.</td>', 'nice, but boring.  also a bit pixelated.  maybe if you had punched up the saturization some, it might be more eye-gripping.', '2007-01-19 23:31:52.000000', NULL, 1),
