(3258215, 452635, 23394, '<td valign="top">nice topic, but you need to work on technique.  it takes a LOT of practice to get this type of shot without visible camera shake.</td>', 'nice topic, but you need to work on technique.  it takes a LOT of practice to get this type of shot without visible camera shake.', '2007-01-19 23:32:09.000000', NULL, 1),
(3258218, 453743, 23394, '<td valign="top">nice topic, but needs a little work on the execution.  don''t get me wrong, i love the image--i just don''t think it meets the challenge that well.</td>', 'nice topic, but needs a little work on the execution.  don''t get me wrong, i love the image--i just don''t think it meets the challenge that well.', '2007-01-19 23:33:24.000000', NULL, 1),
(3258219, 454241, 23394, '<td valign="top">great idea, nice image, could stand to have been just a bit sharper.</td>', 'great idea, nice image, could stand to have been just a bit sharper.', '2007-01-19 23:34:19.000000', NULL, 1),
(3258223, 452131, 23394, '<td valign="top">nice idea, but could use a little more practice in really nailing the focus.</td>', 'nice idea, but could use a little more practice in really nailing the focus.', '2007-01-19 23:35:10.000000', NULL, 1),
(3258224, 453623, 23394, '<td valign="top">definitely a creative take on the challenge...</td>', 'definitely a creative take on the challenge...', '2007-01-19 23:35:57.000000', NULL, 1),
(3258228, 454017, 23394, '<td valign="top">i''m surprised you haven''t had a visit from the boys in the black broncos, yet...<br/> <br/>nice work, btw.</td>', 'i''m surprised you haven''t had a visit from the boys in the black broncos, yet... nice work, btw.', '2007-01-19 23:36:54.000000', NULL, 1),
(3258230, 454212, 23394, '<td valign="top">i think this is what they had in mind when they put the challenge out there.  excellent shot.</td>', 'i think this is what they had in mind when they put the challenge out there.  excellent shot.', '2007-01-19 23:37:35.000000', NULL, 1),
(3258231, 453711, 23394, '<td valign="top">i get the point, but i think it will probably be a bit too subtle for most of this crowd.</td>', 'i get the point, but i think it will probably be a bit too subtle for most of this crowd.', '2007-01-19 23:38:22.000000', NULL, 1),
(3258236, 453532, 23394, '<td valign="top">excellent take on the challenge.  i love it, but can''t help but wonder if the image would be a bit more dynamic if it had just a bit more breathing room.  the way you''ve filled the frame takes away some of the potential energy.</td>', 'excellent take on the challenge.  i love it, but can''t help but wonder if the image would be a bit more dynamic if it had just a bit more breathing room.  the way you''ve filled the frame takes away some of the potential energy.', '2007-01-19 23:39:42.000000', NULL, 1),
(3258238, 452393, 23394, '<td valign="top">nice idea, but the execution could use a little work.  this would have been much stronger with the engine coming towards you, rather than away from you.  you also need to work on controlling your camera shake.</td>', 'nice idea, but the execution could use a little work.  this would have been much stronger with the engine coming towards you, rather than away from you.  you also need to work on controlling your camera shake.', '2007-01-19 23:40:48.000000', NULL, 1);
