(3261284, 452952, 64994, '<td valign="top">The concept for this challenge is that the background is blurred and the moving objects are in focus.</td>', 'The concept for this challenge is that the background is blurred and the moving objects are in focus.', '2007-01-21 00:28:31.000000', NULL, 1),
(3261343, 453742, 63622, '<td valign="top">Amazing perspective..very original viewpoint. I like all the parallel lines coming toward the rider. The handle bars add interest to the shot. Any one can relate to this shot and it brings up emotional feelings in the viewer which few photographers can achieve...nice shot</td>', 'Amazing perspective..very original viewpoint. I like all the parallel lines coming toward the rider. The handle bars add interest to the shot. Any one can relate to this shot and it brings up emotional feelings in the viewer which few photographers can achieve...nice shot', '2007-01-21 00:55:26.000000', NULL, 1),
(3261349, 454311, 63622, '<td valign="top">Cool perspective... i love the bold colors...Composition is good, but slightly centered for my taste but it still works. It almost relates a moment of calmness in midst of chaos.</td>', 'Cool perspective... i love the bold colors...Composition is good, but slightly centered for my taste but it still works. It almost relates a moment of calmness in midst of chaos.', '2007-01-21 00:57:19.000000', NULL, 1),
(3261576, 453539, 49969, '<td valign="top">This is not panning, it''s just slow shutter.</td>', 'This is not panning, it''s just slow shutter.', '2007-01-21 04:47:49.000000', NULL, 1),
