(3265672, 454141, 30982, '<td valign="top">Love it!  Not only is the photograph quite good, but the concept of unicycling in the snow is quite delightful.  The white/gray background is perfect for the shot.</td>', 'Love it!  Not only is the photograph quite good, but the concept of unicycling in the snow is quite delightful.  The white/gray background is perfect for the shot.', '2007-01-22 09:15:12.000000', NULL, 1),
(3265675, 452581, 30982, '<td valign="top">Very good job of either panning or tracking - I like how the white line is solid - nice contrast to the blur in the background and foreground.</td>', 'Very good job of either panning or tracking - I like how the white line is solid - nice contrast to the blur in the background and foreground.', '2007-01-22 09:16:10.000000', NULL, 1),
(3265678, 452479, 30982, '<td valign="top">Classic and very well captured.</td>', 'Classic and very well captured.', '2007-01-22 09:16:35.000000', NULL, 1),
(3265684, 452541, 30982, '<td valign="top">You picked a great spot for this - the background works well.</td>', 'You picked a great spot for this - the background works well.', '2007-01-22 09:17:55.000000', NULL, 1),
(3265688, 451348, 30982, '<td valign="top">I like the everyday feel of this with the stop sign, the neighborhood street.  The wisp of hair blowing up adds to the idea of "speed", too.</td>', 'I like the everyday feel of this with the stop sign, the neighborhood street.  The wisp of hair blowing up adds to the idea of "speed", too.', '2007-01-22 09:19:08.000000', NULL, 1),
(3265693, 454075, 30982, '<td valign="top">Good job.  This is what I tried and you did a much better job actually capturing it!</td>', 'Good job.  This is what I tried and you did a much better job actually capturing it!', '2007-01-22 09:19:45.000000', NULL, 1),
(3265696, 453977, 30982, '<td valign="top">More stopped motion with shallow DOF but a great shot just the same.</td>', 'More stopped motion with shallow DOF but a great shot just the same.', '2007-01-22 09:20:27.000000', NULL, 1),
(3265701, 454265, 30982, '<td valign="top">Cool, I like how the biker is almost invisible - as it seems we always are when on the road...</td>', 'Cool, I like how the biker is almost invisible - as it seems we always are when on the road...', '2007-01-22 09:21:29.000000', NULL, 1),
(3265707, 453816, 30982, '<td valign="top">Textbook panning and done beautifully.</td>', 'Textbook panning and done beautifully.', '2007-01-22 09:22:33.000000', NULL, 1),
(3265719, 453742, 30982, '<td valign="top">Great perspective - much braver and more skilled than I am, too!</td>', 'Great perspective - much braver and more skilled than I am, too!', '2007-01-22 09:25:38.000000', NULL, 1),
(3265722, 454151, 30982, '<td valign="top">Wonderful sense of fluidity to this.</td>', 'Wonderful sense of fluidity to this.', '2007-01-22 09:26:36.000000', NULL, 1),
