(3265795, 453974, 30982, '<td valign="top">Cute!  They really are tiny little things, aren''t they?  I like the light trails, both behind and in the reflections.</td>', 'Cute!  They really are tiny little things, aren''t they?  I like the light trails, both behind and in the reflections.', '2007-01-22 09:48:26.000000', NULL, 1),
(3265888, 454036, 30982, '<td valign="top">This is quite lovely!</td>', 'This is quite lovely!', '2007-01-22 10:14:15.000000', NULL, 1),
(3265898, 453439, 30982, '<td valign="top">One of my favorites.  Probably too much motion blur on the subject for some, but I really like the image.</td>', 'One of my favorites.  Probably too much motion blur on the subject for some, but I really like the image.', '2007-01-22 10:16:36.000000', NULL, 1),
(3266017, 452433, 30982, '<td valign="top">Looks like a critter of some kind, doesn''t it?</td>', 'Looks like a critter of some kind, doesn''t it?', '2007-01-22 10:40:40.000000', NULL, 1),
