(3267524, 451993, 40819, '<td valign="top">This is good but if the background was lighter it would have been great.</td>', 'This is good but if the background was lighter it would have been great.', '2007-01-22 16:33:11.000000', NULL, 1),
(3267532, 453933, 40819, '<td valign="top">This is more stop action since the background has such bokeh and you can see the lens is not panning. However for a capture of a hawk it is an outstanding shot.</td>', 'This is more stop action since the background has such bokeh and you can see the lens is not panning. However for a capture of a hawk it is an outstanding shot.', '2007-01-22 16:34:34.000000', NULL, 1),
