(3270673, 454036, 6532, '<td valign="top">Something about this picture is very intriguing.  I could see this printed on a texture.  I like the colors and framing.  Although others may not like it - I think it is a 10!</td>', 'Something about this picture is very intriguing.  I could see this printed on a texture.  I like the colors and framing.  Although others may not like it - I think it is a 10!', '2007-01-23 11:55:28.000000', NULL, 1),
(3270684, 454143, 6532, '<td valign="top">Cool background.  It almost looks like a watercolor!  May need to increase the contrast of the birds so that they stand out more.</td>', 'Cool background.  It almost looks like a watercolor!  May need to increase the contrast of the birds so that they stand out more.', '2007-01-23 11:59:13.000000', NULL, 1),
(3270741, 452335, 71767, '<td valign="top">I would expect more background blur indicating movement in a motion panning shot</td>', 'I would expect more background blur indicating movement in a motion panning shot', '2007-01-23 12:25:30.000000', NULL, 1),
