(3270770, 453489, 71767, '<td valign="top">Nice shot, it would be nice to have a little bit more space in front of the car for a better composition</td>', 'Nice shot, it would be nice to have a little bit more space in front of the car for a better composition', '2007-01-23 12:36:25.000000', NULL, 1),
