(3271415, 453922, 34938, '<td valign="top">I love the look on her face...I would have cropped just a little bit of the neg space on the top, other than that...great shot<br/> <br/>(Lesley is that you?)</td>', 'I love the look on her face...I would have cropped just a little bit of the neg space on the top, other than that...great shot (Lesley is that you?)', '2007-01-23 15:57:13.000000', NULL, 1),
(3271418, 452766, 34938, '<td valign="top">excellent bike image...would do well in a magazine...well done</td>', 'excellent bike image...would do well in a magazine...well done', '2007-01-23 15:57:44.000000', NULL, 1),
(3271421, 453278, 34938, '<td valign="top">great light and motion blur...well done</td>', 'great light and motion blur...well done', '2007-01-23 15:58:31.000000', NULL, 1),
(3271422, 454194, 34938, '<td valign="top">coveys great drama, well done</td>', 'coveys great drama, well done', '2007-01-23 15:58:57.000000', NULL, 1),
(3271434, 453933, 34938, '<td valign="top">there''s no real motion panning here...the bird looks like it''s hovering and the bg is static...great image, but not for this challenge</td>', 'there''s no real motion panning here...the bird looks like it''s hovering and the bg is static...great image, but not for this challenge', '2007-01-23 16:02:13.000000', NULL, 1),
