INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3274905, 453967, 30982, '<td valign="top">In a way it''s kinda sad that voters here tend to "look for the obvious" - I''m betting that a good number of them actually liked this when they first saw it, then said to themselves "Oh, but nothing''s in focus and there''s a lens flare there."  Very sad indeed, as they miss out on the shots that actually have life to them.</td>', 'In a way it''s kinda sad that voters here tend to "look for the obvious" - I''m betting that a good number of them actually liked this when they first saw it, then said to themselves "Oh, but nothing''s in focus and there''s a lens flare there."  Very sad indeed, as they miss out on the shots that actually have life to them.', '2007-01-24 09:30:58.000000', NULL, 0),
